selector_to_html = {"a[href=\"#pyskyfire.network.blocks.DiffuserBlock.post_process\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.DiffuserBlock.post_process\">\n<span class=\"sig-name descname\"><span class=\"pre\">post_process</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signals</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the detailed diffuser result at the converged inlet condition.</p></dd>", "a[href=\"#pyskyfire.network.blocks.DiffuserBlock._solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.DiffuserBlock._solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">_solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">station</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../engine_network/Station.html#pyskyfire.network.engine_network.Station\" title=\"pyskyfire.network.engine_network.Station\"><span class=\"pre\">Station</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire-network-blocks-diffuserblock\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.network.blocks.DiffuserBlock<a class=\"headerlink\" href=\"#pyskyfire-network-blocks-diffuserblock\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.network.blocks.DiffuserBlock\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.DiffuserBlock\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.network.blocks.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DiffuserBlock</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_out</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diffuser</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">FluidBlock</span></code></p><p>Engine-network adapter for one <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">VanedDiffuser</span></code>.</p><p>Sits between a pump block, whose outlet is the impeller outlet, and the\nvolute that collects the diffuser\u2019s discharge. It hands the network\u2019s\ninlet station to <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">VanedDiffuser.solve()</span></code> and emits the outlet station\nand a <code class=\"docutils literal notranslate\"><span class=\"pre\">dp_&lt;name&gt;</span></code> loss signal. The geometry is resolved when the\ndiffuser is designed, so the network may iterate the operating point\nfreely. The diffuser is adiabatic; the outlet carries the inlet\ntemperature, as a volute\u2019s does.</p></dd>", "a[href=\"../engine_network/Station.html#pyskyfire.network.engine_network.Station\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.engine_network.Station\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.network.engine_network.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Station</span></span></dt><dd><p>Thermodynamic state container used by the engine network.</p></dd>", "a[href=\"#pyskyfire.network.blocks.DiffuserBlock.compute\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.DiffuserBlock.compute\">\n<span class=\"sig-name descname\"><span class=\"pre\">compute</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">signals</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute one pass of the block.</p><p class=\"rubric\">Notes</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
